// Game: Asteroid Dodge
// Canvas size: 800x600 (as per IDEA.md)
// Player: small ship (rectangle) controlled by Arrow keys/A/D and boost with Space.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) {
    console.error('Canvas with id "game" not found');
    return;
  }
  canvas.width = 800;
  canvas.height = 600;
  const ctx = canvas.getContext('2d');

  // Player definition
  const player = {
    width: 40,
    height: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 40,
    speed: 4,
    boostSpeed: 8,
    dx: 0,
    color: '#0f0',
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
  });
  window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
  });

  // Asteroid pool
  const asteroids = [];
  let asteroidSpawnTimer = 0;
  const baseSpawnInterval = 90; // frames
  let spawnInterval = baseSpawnInterval;
  let asteroidSpeed = 2;

  let score = 0;
  let startTime = performance.now();
  let gameOver = false;

  function spawnAsteroid() {
    const size = Math.random() * 30 + 20; // 20-50px
    const x = Math.random() * (canvas.width - size);
    asteroids.push({ x, y: -size, size, speed: asteroidSpeed });
  }

  function update() {
    if (gameOver) return;
    // Player movement
    player.dx = 0;
    if (keys.ArrowLeft || keys.a) player.dx = -player.speed;
    if (keys.ArrowRight || keys.d) player.dx = player.speed;
    if (keys[' ']) player.dx = (keys.ArrowLeft || keys.a) ? -player.boostSpeed : (keys.ArrowRight || keys.d) ? player.boostSpeed : 0;
    player.x += player.dx;
    // Keep inside bounds
    if (player.x < 0) player.x = 0;
    if (player.x + player.width > canvas.width) player.x = canvas.width - player.width;

    // Spawn asteroids
    asteroidSpawnTimer++;
    if (asteroidSpawnTimer >= spawnInterval) {
      spawnAsteroid();
      asteroidSpawnTimer = 0;
      // Gradually increase difficulty
      if (spawnInterval > 30) spawnInterval -= 0.5;
      asteroidSpeed += 0.01;
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Remove off-screen
      if (a.y - a.size > canvas.height) asteroids.splice(i, 1);
      // Collision detection (simple AABB)
      if (
        a.x < player.x + player.width &&
        a.x + a.size > player.x &&
        a.y < player.y + player.height &&
        a.y + a.size > player.y
      ) {
        gameOver = true;
        break;
      }
    }

    // Score based on survival time
    score = Math.floor((performance.now() - startTime) / 1000);
  }

  function draw() {
    // Clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw player (simple triangle ship)
    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.moveTo(player.x, player.y + player.height);
    ctx.lineTo(player.x + player.width / 2, player.y);
    ctx.lineTo(player.x + player.width, player.y + player.height);
    ctx.closePath();
    ctx.fill();

    // Draw asteroids (circles)
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText(`Score: ${score}s`, 10, 20);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start the game
  requestAnimationFrame(loop);
})();
